import styled from '@emotion/styled';

export const PowerBookContainer = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '16px',
  padding: '0 24px 20px',
});

export const StyledPaddingContainer = styled.div({
  padding: '0px 20px 24px',
});
